-- Talent Hub: rule-based cohorts of people, with updates posted to them. Additive. Applied 2026-11-18.
CREATE TABLE IF NOT EXISTS "TalentCohort" ("id" TEXT NOT NULL, "institutionId" TEXT NOT NULL, "name" TEXT NOT NULL, "purpose" TEXT, "industries" TEXT[] DEFAULT ARRAY[]::TEXT[], "functions" TEXT[] DEFAULT ARRAY[]::TEXT[], "levels" TEXT[] DEFAULT ARRAY[]::TEXT[], "minWeeksOut" INTEGER, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TalentCohort_pkey" PRIMARY KEY ("id"), CONSTRAINT "TalentCohort_institutionId_fkey" FOREIGN KEY ("institutionId") REFERENCES "Institution"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "TalentCohort_institutionId_idx" ON "TalentCohort"("institutionId");
CREATE TABLE IF NOT EXISTS "TalentCohortPost" ("id" TEXT NOT NULL, "cohortId" TEXT NOT NULL, "body" TEXT NOT NULL, "authorLabel" TEXT NOT NULL, "createdBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "TalentCohortPost_pkey" PRIMARY KEY ("id"), CONSTRAINT "TalentCohortPost_cohortId_fkey" FOREIGN KEY ("cohortId") REFERENCES "TalentCohort"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX IF NOT EXISTS "TalentCohortPost_cohortId_createdAt_idx" ON "TalentCohortPost"("cohortId", "createdAt");
